import { View, Text, TextInput, StyleSheet } from "react-native";
import { useState } from "react";
import { registerRootComponent } from "expo";

function App() {
  const [email, setEmail] = useState("");
  return (
    <View style={styles.screen}>
      <TextInput nativeID="email" style={styles.input} placeholder="И-мэйл" keyboardType="email-address"
        value={email} onChangeText={setEmail} />
      {/* энд бичнэ үү: email @ агуулаагүй бол алдаа Text харуул (nativeID="err") */}
    </View>
  );
}

const styles = StyleSheet.create({
  screen: { flex: 1, padding: 24, gap: 10, justifyContent: "center" },
  input: { borderWidth: 1, borderColor: "#cbd5e1", borderRadius: 10, padding: 14 },
  err: { color: "#dc2626" },
});

registerRootComponent(App);

import { View, Text, TextInput, StyleSheet } from "react-native";
import { useState } from "react";
import { registerRootComponent } from "expo";

function App() {
  const [email, setEmail] = useState("");
  return (
    <View style={styles.screen}>
      <TextInput nativeID="email" style={styles.input} placeholder="И-мэйл" keyboardType="email-address"
        value={email} onChangeText={setEmail} />
      {email.length > 0 && !email.includes("@") && (
        <Text nativeID="err" style={styles.err}>И-мэйл буруу байна (@ алга)</Text>
      )}
    </View>
  );
}

const styles = StyleSheet.create({
  screen: { flex: 1, padding: 24, gap: 10, justifyContent: "center" },
  input: { borderWidth: 1, borderColor: "#cbd5e1", borderRadius: 10, padding: 14 },
  err: { color: "#dc2626" },
});

registerRootComponent(App);
